/* ================= v44: Voice studio — range, daily workout, sustain & vibrato, breath, dynamics, sight-singing, voice health ================= */
/* gliding guide tone for sirens and glides (the lane used to stay silent on these) */
function svGlide(m0,m1,t,d){const c=AC;if(!c)return;const f=m=>440*Math.pow(2,(m-69)/12);const o=c.createOscillator();o.type='triangle';const o2=c.createOscillator();o2.type='sine';const g2=c.createGain();g2.gain.value=.35;const lp=c.createBiquadFilter();lp.type='lowpass';lp.frequency.value=2200;const g=c.createGain();
 [o,o2].forEach((x,i)=>{x.frequency.setValueAtTime(f(m0)*(i?2:1),t);x.frequency.exponentialRampToValueAtTime(f(m1)*(i?2:1),t+d)});g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.16,t+.06);g.gain.setValueAtTime(.16,Math.max(t+.07,t+d-.1));g.gain.exponentialRampToValueAtTime(.0001,t+d);
 o.connect(lp);o2.connect(g2);g2.connect(lp);lp.connect(g);g.connect(MASTER);o.start(t);o2.start(t);o.stop(t+d+.03);o2.stop(t+d+.03)}
/* ---------- your measured range ---------- */
const VS_TYPES=[['Bass',40,64,[57,62]],['Baritone',45,69,[59,64]],['Tenor',48,72,[62,67]],['Alto',53,77,[64,72]],['Mezzo-soprano',57,81,[64,76]],['Soprano',60,84,[65,78]]];
const vsRange=()=>{const r=store.get('svrange',null);return r&&r.lo<r.hi?r:null};
const vsCentreOf=r=>Math.round(r.lo+(r.hi-r.lo)*.42);
function vsSyncType(){const r=vsRange();const i=SV_TYPES.findIndex(x=>x[0]==='mine');if(!r){if(i>=0)SV_TYPES.splice(i,1);return}const row=['mine','My range',vsCentreOf(r),`${svName(r.lo)} to ${svName(r.hi)}, measured`];if(i>=0)SV_TYPES[i]=row;else SV_TYPES.push(row)}
vsSyncType();
function vsSetRange(lo,hi,how){lo=Math.round(lo);hi=Math.round(hi);if(hi-lo<5)return false;const r={lo,hi,date:todayKey(),how};store.set('svrange',r);const H=store.get('svrangeh',[])||[];const last=H[H.length-1];if(last&&last.date===r.date)H[H.length-1]=r;else H.push(r);store.set('svrangeh',H.slice(-40));vsSyncType();store.set('svtype','mine');return true}
function vsGuessType(r){let best=null,bd=1e9;VS_TYPES.forEach(t=>{const d=Math.abs(r.lo-t[1])+Math.abs(r.hi-t[2]);if(d<bd){bd=d;best=t}});return best}
/* the comfortable part of your range, used to place every exercise */
function vsZone(){const r=vsRange();if(r)return{lo:r.lo+2,hi:r.hi-2,mid:vsCentreOf(r),measured:true};const c=svCentre();return{lo:c-7,hi:c+9,mid:c,measured:false}}
function vsFit(span,{reps=5}={}){const Z=vsZone();const top=Z.hi-span;const start=Math.min(Math.max(Z.lo,Z.mid-Math.round(span/2)-2),top);const n=Math.max(1,Math.min(reps,top-start+1));return{start,n}}
/* pattern helpers: up through the comfortable range, then back down */
function vsUpDown(pat,{bpm=84,call=true,reps=5,step=1}={}){const span=Math.max(...pat.flatMap(p=>p[0]==='g'?[p[1],p[2]]:[p[0]]));const F=vsFit(span,{reps});const roots=[];for(let i=0;i<F.n;i++)roots.push(F.start+i*step);for(let i=F.n-2;i>=0&&roots.length<F.n*2-1;i--)roots.push(F.start+i*step);
 const b=60/bpm;const out=[];let t=0;roots.forEach(r=>{const notes=pat.map(p=>p[0]==='g'?{m:r+p[1],glide:r+p[2],d:p[3]*b}:{m:r+p[0],d:p[1]*b,label:p[2]||''});
  if(call){notes.forEach(n=>{out.push({...n,t,play:true,sing:false,label:''});t+=n.d});t+=b*.5}notes.forEach(n=>{out.push({...n,t,play:!call,sing:true});t+=n.d});t+=b*.75});return out}
/* ---------- live pitch helpers ---------- */
function vsMidi(){return svMidiNow()}
function vsDb(){const l=INPUT.level||0;return l>0?20*Math.log10(l):-120}
function vsMicNote(){return IN_CLAUDE()?`<p class="callout">Inside Claude this page can't use your microphone, so there's no live pitch here. You can still listen and sing along, and use the timers. For live feedback, open Theory Club on the website or in the desktop app.</p>`:inputPanelHTML()}
function vsBindMic(host,re){const ip=host.querySelector('.inpanel');if(ip)bindInputPanel(ip,()=>re&&re())}
/* stable-note detector: returns a held note once the voice stays within half a semitone for ~0.4 s */
function vsHeld(){let buf=[];return m=>{const t=performance.now();if(m==null){buf=[];return null}buf.push([t,m]);buf=buf.filter(x=>t-x[0]<450);if(buf.length<8||t-buf[0][0]<380)return null;const ms=buf.map(x=>x[1]).sort((a,b)=>a-b);const lo=ms[Math.floor(ms.length*.1)],hi=ms[Math.ceil(ms.length*.9)-1];return hi-lo<1.7?ms[ms.length>>1]:null}}
/* ---------- 1. range finder ---------- */
function vsRangeWidget(host){let phase=null,lo=null,hi=null,raf=0,t0=0;const held=vsHeld();
 const R=vsRange();const render=()=>{cancelAnimationFrame(raf);const r=vsRange();const T=r?vsGuessType(r):null;
  host.innerHTML=`<h3>Find your range</h3><p class="hint">Every exercise in the studio is placed inside your comfortable range. Measure it once now and again every month or so: it grows with practice.</p>${vsMicNote()}
  ${r?`<div class="vsrange">${vsRangeSVG(r)}<p><b>${svName(r.lo)} to ${svName(r.hi)}</b> <span class="hint">· ${r.hi-r.lo} semitones · measured ${parseKey(r.date).toLocaleDateString(undefined,{day:'numeric',month:'short'})}</span></p>
   <p>Your range is closest to a typical <b>${T[0].toLowerCase()}</b> (about ${svName(T[1])} to ${svName(T[2])}). Many ${T[0].toLowerCase()}s feel their voice shift gear around ${svName(T[3][0])}${T[3][1]!==T[3][0]?` and again near ${svName(T[3][1])}`:''}; sirens through that area smooth it out.</p>
   <p class="hint">Range is only one clue to voice type. Where your voice sounds and feels best (your tessitura) and its colour matter more, and a teacher can help you decide. Many beginners gain several notes at each end within months.</p></div>`:''}
  ${IN_CLAUDE()?'':`<div class="vsteps"><div class="vstep ${phase==='lo'?'on':''}"><b>1. Lowest note</b><span class="hint">Sigh down on “ah” from a comfortable note to your lowest clear note, and hold it. Stop before it turns croaky.</span><button class="btn small ${phase==='lo'?'':'primary'}" data-ph="lo">${phase==='lo'?'Done':'Start'}</button><span class="vsv" id="vslo">${lo!=null?svName(lo):'–'}</span></div>
   <div class="vstep ${phase==='hi'?'on':''}"><b>2. Highest note</b><span class="hint">Siren up on “oo” or “ng” to the highest note you can hold without straining, and hold it. Falsetto counts.</span><button class="btn small ${phase==='hi'?'':'primary'}" data-ph="hi" ${lo==null?'disabled':''}>${phase==='hi'?'Done':'Start'}</button><span class="vsv" id="vshi">${hi!=null?svName(hi):'–'}</span></div>
   <p class="hint" id="vslive" aria-live="polite">${phase?'Listening…':LISTEN()?'Press Start for step 1.':'Connect your microphone first.'}</p>
   ${lo!=null&&hi!=null&&!phase?`<div class="row"><button class="btn primary" id="vssave">Save ${svName(lo)} to ${svName(hi)}</button></div>`:''}</div>`}
  <details class="more" ${IN_CLAUDE()?'open':''}><summary>Set it by ear instead</summary><p class="hint">Play notes, sing along, and pick the lowest and highest you can sing comfortably.</p>
   <div class="row" style="gap:10px;align-items:flex-end"><label class="popt">Lowest <select id="vsml">${vsNoteOpts(r?r.lo:svCentre()-10)}</select></label><button class="btn small" data-pl="vsml">▶</button><label class="popt">Highest <select id="vsmh">${vsNoteOpts(r?r.hi:svCentre()+10)}</select></label><button class="btn small" data-pl="vsmh">▶</button><button class="btn small" id="vsmsave">Save</button></div></details>`;
  vsBindMic(host,render);
  host.querySelectorAll('[data-ph]').forEach(b=>b.onclick=()=>{const p=b.dataset.ph;if(phase===p){phase=null;render();return}if(!LISTEN()){toast('Connect your microphone first.');return}phase=p;if(p==='lo')lo=null;else hi=null;t0=performance.now();render();loop()});
  const sv=host.querySelector('#vssave');if(sv)sv.onclick=()=>{if(vsSetRange(lo,hi,'mic')){toast('Range saved');lo=hi=null;render()}else toast('That range looks too small. Try again.')};
  host.querySelectorAll('[data-pl]').forEach(b=>b.onclick=()=>{const a=audio();if(a)svPlayNote(+host.querySelector('#'+b.dataset.pl).value,a.currentTime+.05,1.2)});
  host.querySelector('#vsmsave').onclick=()=>{const l=+host.querySelector('#vsml').value,h=+host.querySelector('#vsmh').value;if(vsSetRange(Math.min(l,h),Math.max(l,h),'ear')){toast('Range saved');render()}else toast('Pick notes at least five semitones apart.')}};
 const loop=()=>{if(!document.body.contains(host)||!phase)return;const m=vsMidi();const h=held(m);const live=host.querySelector('#vslive');
  if(h!=null){if(phase==='lo'&&(lo==null||h<lo)){lo=Math.round(h);host.querySelector('#vslo').textContent=svName(lo)}if(phase==='hi'&&(hi==null||h>hi)&&(lo==null||h>lo+4)){hi=Math.round(h);host.querySelector('#vshi').textContent=svName(hi)}}
  if(live)live.textContent=m!=null?`Hearing ${svName(m)}${h!=null?' (held)':''}`:'Listening…';if(performance.now()-t0>20000){phase=null;render();return}raf=requestAnimationFrame(loop)};
 render()}
function vsNoteOpts(sel){let o='';for(let m=33;m<=91;m++)o+=`<option value="${m}" ${m===sel?'selected':''}>${svName(m)}</option>`;return o}
function vsRangeSVG(r){const L=33,H=91,W=560,x=m=>12+(m-L)/(H-L)*(W-24);const types=VS_TYPES.map((t,i)=>`<rect x="${x(t[1])}" y="${8+i*11}" width="${x(t[2])-x(t[1])}" height="7" rx="3.5" class="vstb"/><text x="${x(t[1])-4}" y="${14+i*11}" text-anchor="end" class="vstt">${t[0]}</text>`).join('');
 const cs=[36,48,60,72,84].map(m=>`<line x1="${x(m)}" x2="${x(m)}" y1="4" y2="${8+VS_TYPES.length*11+30}" class="vstg"/><text x="${x(m)}" y="${8+VS_TYPES.length*11+42}" text-anchor="middle" class="vstt">${svName(m)}</text>`).join('');
 const y=8+VS_TYPES.length*11+8;return`<svg class="vsrsvg" viewBox="0 0 ${W} ${y+40}" role="img" aria-label="Your range ${svName(r.lo)} to ${svName(r.hi)} compared with typical voice types">${cs}${types}<rect x="${x(r.lo)}" y="${y}" width="${x(r.hi)-x(r.lo)}" height="14" rx="7" class="vsyou"/><rect x="${x(r.lo+2)}" y="${y+4}" width="${Math.max(2,x(r.hi-2)-x(r.lo+2))}" height="6" rx="3" class="vszone"/><text x="${x(r.lo)-4}" y="${y+11}" text-anchor="end" class="vstt b">You</text></svg>`}
/* ---------- 2. sustain, steadiness and vibrato ---------- */
function vsAnalyse(S){/* S: [{t (s), c (cents from target)}] voiced samples */if(S.length<20)return null;
 let runs=[],cur=[S[0]];for(let i=1;i<S.length;i++){if(S[i].t-S[i-1].t>.25){runs.push(cur);cur=[]}cur.push(S[i])}runs.push(cur);const run=runs.sort((a,b)=>(b[b.length-1].t-b[0].t)-(a[a.length-1].t-a[0].t))[0];
 const dur=run[run.length-1].t-run[0].t;const cs=run.map(x=>x.c);const mean=cs.reduce((a,b)=>a+b,0)/cs.length;
 /* separate slow drift from fast wobble with a 0.35 s moving average */const W=.35;const sm=run.map((p,i)=>{let s=0,n=0;for(let j=i;j>=0&&p.t-run[j].t<=W/2;j--){s+=run[j].c;n++}for(let j=i+1;j<run.length&&run[j].t-p.t<=W/2;j++){s+=run[j].c;n++}return s/n});
 const inTune=sm.filter(c=>Math.abs(c)<35).length/sm.length;const res=run.map((p,i)=>p.c-sm[i]);const rms=Math.sqrt(res.reduce((a,b)=>a+b*b,0)/res.length);const extent=Math.round(rms*2*Math.SQRT2);
 let zc=0;for(let i=1;i<res.length;i++)if((res[i-1]<0)!==(res[i]<0)&&Math.abs(res[i]-res[i-1])>4)zc++;const rate=dur>0?+(zc/2/dur).toFixed(1):0;
 const drift=Math.round(Math.sqrt(sm.reduce((a,b)=>a+(b-mean)**2,0)/sm.length));const half=Math.floor(run.length/2);const m1=sm.slice(0,half).reduce((a,b)=>a+b,0)/Math.max(1,half),m2=sm.slice(half).reduce((a,b)=>a+b,0)/Math.max(1,run.length-half);
 return{dur:+dur.toFixed(1),mean:Math.round(mean),inTune:Math.round(inTune*100),extent,rate,drift,sag:Math.round(m2-m1),vib:extent>=30&&rate>=3.5&&rate<=9}}
function vsSustainAdvice(A,mode){const t=[];if(!A)return['I didn\'t hear a long enough note. Sing a little louder and hold it for at least two seconds.'];
 if(Math.abs(A.mean)>=20)t.push(`On average you were ${Math.abs(A.mean)} cents ${A.mean>0?'sharp':'flat'}. ${A.mean>0?'Relax the jaw and think of the note as slightly lower and rounder.':'Keep the breath moving and think of the note as slightly higher and brighter.'}`);
 if(A.sag<=-20)t.push(`The pitch sagged by ${-A.sag} cents as the note went on: that usually means the breath support faded. Take a fuller breath and keep the ribs open to the end.`);else if(A.sag>=20)t.push(`The pitch crept up by ${A.sag} cents as you held it, often from pushing. Ease off the volume.`);
 if(A.drift>25)t.push('The pitch wandered slowly. Practise with “Play the note” on, and hum it before you open to the vowel.');
 if(mode==='straight'){if(A.vib)t.push(`There was vibrato (${A.rate} times a second). For a straight tone, sing a little lighter and keep the breath very even.`);}
 else{if(!A.vib&&A.extent<30)t.push('That was a straight tone. Vibrato usually appears on its own when the throat is relaxed and the breath is steady; try a slightly longer, freer note rather than forcing it.');
  else if(A.rate>7.5)t.push(`Your vibrato is fast (${A.rate} a second). That can come from tension in the throat or tongue. Sing a little softer and let it slow down.`);
  else if(A.rate<4.5&&A.vib)t.push(`Your vibrato is slow (${A.rate} a second), which can sound like a wobble. Lighter, brighter singing usually tightens it up.`);
  else if(A.vib)t.push(`Healthy vibrato: about ${A.rate} times a second, ${A.extent} cents wide. Most trained singers sit between 5 and 7 a second.`);
  if(A.vib&&A.extent>160)t.push('The vibrato is very wide. Ease off the volume to narrow it.')}
 if(!t.length)t.push('Steady and in tune. Try the same note on a different vowel, or a little higher.');return t}
function vsSustainWidget(host,o={}){let mode=o.mode||'free',target=null,S=[],raf=0,t0=0,on=false,last=null;const Z=vsZone();const opts=[];for(let m=Z.lo;m<=Z.hi;m++)opts.push(m);target=o.note||Z.mid;if(target<Z.lo||target>Z.hi)target=Z.mid;
 const best=()=>+store.get('svsustain',0)||0;
 const render=()=>{cancelAnimationFrame(raf);host.innerHTML=`<h3>${esc(o.title||'Hold a note')}</h3><p class="hint">${esc(o.hint||'Hear the note, then sing it on a comfortable vowel and hold it as long as is easy. The line shows how far you are from the note in cents (100 cents is a semitone).')}</p>${vsMicNote()}
  <div class="row" style="gap:10px;align-items:flex-end"><label class="popt">Note <select id="vssn">${opts.map(m=>`<option value="${m}" ${m===target?'selected':''}>${svName(m)}</option>`).join('')}</select></label>${o.mode?'':pillsHTML('vsm',[['free','Natural'],['straight','Straight tone'],['vib','Vibrato']],mode)}
   <button class="btn primary small" id="vsgo">${ICON.play} ${on?'Stop':'Start'}</button><span class="hint">Best hold ${best()} s</span></div>
  <canvas class="vscv" width="1520" height="360"></canvas><p class="hint" id="vsst" aria-live="polite">${LISTEN()?'Press Start: you\'ll hear the note, then sing.':IN_CLAUDE()?'Press Start to hear the note and sing along with the timer.':'Connect your microphone to see your pitch.'}</p><div class="vsres">${last?vsResHTML(last,mode):''}</div>`;
  vsBindMic(host,render);bindPills(host,(g,v)=>{if(g==='vsm'){mode=v;render()}});host.querySelector('#vssn').onchange=e=>{target=+e.target.value;const a=audio();if(a)svPlayNote(target,a.currentTime+.05,1)};
  host.querySelector('#vsgo').onclick=()=>{if(on){stop();return}const a=audio();if(!a)return;svPlayNote(target,a.currentTime+.05,1.6);S=[];on=true;t0=a.currentTime+1.7;host.querySelector('#vsgo').innerHTML=`${ICON.play} Stop`;draw()};idle()};
 const idle=()=>{const cv=host.querySelector('.vscv');if(!cv)return;const g=cv.getContext('2d');const W=760,H=180;g.setTransform(2,0,0,2,0,0);g.fillStyle=svCss('--surface-2');g.fillRect(0,0,W,H);const y=c=>H/2-c*(H/2-12)/150;g.fillStyle=svCss('--good-soft');g.fillRect(0,y(35),W,y(-35)-y(35));g.strokeStyle=svCss('--line');g.lineWidth=1;[-100,-50,0,50,100].forEach(c=>{g.beginPath();g.moveTo(0,y(c));g.lineTo(W,y(c));g.stroke()});g.fillStyle=svCss('--muted');g.font='11px system-ui';g.fillText('sharp',6,y(110));g.fillText('flat',6,y(-120));g.fillText('in tune',6,y(0)-4);if(last&&last.S&&last.S.length){const S2=last.S;const span=Math.max(10,S2[S2.length-1].t+1);const x=t=>30+t/span*(W-40);g.strokeStyle=svCss('--accent');g.lineWidth=2.5;g.beginPath();S2.forEach((p,i)=>{if(!i||p.t-S2[i-1].t>.2)g.moveTo(x(p.t),y(Math.max(-150,Math.min(150,p.c))));else g.lineTo(x(p.t),y(Math.max(-150,Math.min(150,p.c))))});g.stroke()}};
 const stop=()=>{on=false;cancelAnimationFrame(raf);const A=vsAnalyse(S);last={A,heard:S.length,S:S.slice()};if(A&&A.dur>best())store.set('svsustain',A.dur);const L=store.get('svsus',[])||[];if(A)L.push({d:todayKey(),dur:A.dur,inTune:A.inTune});store.set('svsus',L.slice(-60));render()};
 const draw=()=>{if(!document.body.contains(host)){on=false;return}const cv=host.querySelector('.vscv');if(!cv)return;const g=cv.getContext('2d');const W=760,H=180;g.setTransform(2,0,0,2,0,0);const now=AC.currentTime;const el=now-t0;
  const m=vsMidi();if(el>=0&&m!=null){const c=(svFold(m,target)-target)*100;if(Math.abs(c)<300)S.push({t:el,c})}
  g.clearRect(0,0,W,H);g.fillStyle=svCss('--surface-2');g.fillRect(0,0,W,H);const y=c=>H/2-Math.max(-150,Math.min(150,c))*(H/2-12)/150;g.fillStyle=svCss('--good-soft');g.fillRect(0,y(35),W,y(-35)-y(35));
  g.strokeStyle=svCss('--line');g.lineWidth=1;[-100,-50,0,50,100].forEach(c=>{g.beginPath();g.moveTo(0,y(c));g.lineTo(W,y(c));g.stroke()});g.fillStyle=svCss('--muted');g.font='11px system-ui';g.fillText('sharp',6,y(110));g.fillText('flat',6,y(-120));
  const span=Math.max(10,el+1);const x=t=>30+t/span*(W-40);g.strokeStyle=svCss('--accent');g.lineWidth=2.5;g.beginPath();S.forEach((p,i)=>{if(i&&p.t-S[i-1].t>.2)g.moveTo(x(p.t),y(p.c));else if(i)g.lineTo(x(p.t),y(p.c));else g.moveTo(x(p.t),y(p.c))});g.stroke();
  const st=host.querySelector('#vsst');if(st)st.textContent=el<0?'Listen…':`Sing ${svName(target)} · ${el.toFixed(1)} s${m!=null?` · ${Math.round((svFold(m,target)-target)*100)} cents`:''}`;if(el>40){stop();return}raf=requestAnimationFrame(draw)};
 render()}
function vsResHTML(r,mode){const A=r.A;if(!A)return`<p class="note">${IN_CLAUDE()?'Without the microphone I can\'t measure this, but the timer still shows how long you held it.':'I didn\'t hear a long enough note. Sing a little louder and hold it for at least two seconds.'}</p>`;
 return`<div class="prgrid"><div><span class="prv">${A.dur} s</span><span class="hint">longest hold</span></div><div><span class="prv">${A.inTune}%</span><span class="hint">in tune (centre of the note within 35 cents)</span></div><div><span class="prv">${A.mean>0?'+':''}${A.mean}</span><span class="hint">cents off on average</span></div><div><span class="prv">${A.vib?A.rate+'/s':'–'}</span><span class="hint">${A.vib?`vibrato, ${A.extent} cents wide`:'no vibrato'}</span></div></div><ul>${vsSustainAdvice(A,mode).map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`}
/* ---------- 3. breath ---------- */
function vsBreathWidget(host){let mode='pace',raf=0,on=false,t0=0,cyc=0,quiet=null,hiss=0,best=+store.get('svhiss',0)||0,lastHiss=null;
 const render=()=>{cancelAnimationFrame(raf);host.innerHTML=`<h3>Breath</h3><p class="hint">Steady breath is the engine of singing. Breathe low into your belly and sides, keep the shoulders still, and let the air out slowly and evenly.</p>
  ${pillsHTML('vsb',[['pace','Paced breathing'],['hiss','Hiss timer']],mode)}
  ${mode==='pace'?`<div class="vsbreath"><div class="vsball" id="vsball"></div><p class="vsbtxt" id="vsbtxt">Breathe in for 4, out on a hiss for 8. Five rounds.</p><button class="btn primary small" id="vsbgo">${on?'Stop':'Start'}</button></div>`:
  `<p>Take a full breath and hiss on “sss” as long and evenly as you comfortably can. ${IN_CLAUDE()?'Hold the button down while you hiss.':'The microphone times it.'} Do it three times and keep the best.</p>${IN_CLAUDE()?'':vsMicNote()}
   <div class="vsbreath"><b class="vshiss" id="vshiss">${lastHiss!=null?lastHiss.toFixed(1)+' s':'0.0 s'}</b><button class="btn primary" id="vshgo">${IN_CLAUDE()?'Hold while you hiss':on?'Stop':'Start'}</button><span class="hint">Best ${best.toFixed(1)} s · many adults manage 15–25 s, and it grows with practice</span></div>`}`;
  bindPills(host,(g,v)=>{mode=v;on=false;render()});vsBindMic(host,render);
  const pg=host.querySelector('#vsbgo');if(pg)pg.onclick=()=>{if(on){on=false;render();return}on=true;cyc=0;t0=performance.now();pg.textContent='Stop';pace()};
  const hg=host.querySelector('#vshgo');if(hg){if(IN_CLAUDE()){const st=()=>{t0=performance.now();on=true;tick()},en=()=>{if(!on)return;on=false;finish((performance.now()-t0)/1000)};hg.onpointerdown=st;hg.onpointerup=en;hg.onpointerleave=en}
   else hg.onclick=()=>{if(on){on=false;finish(hiss);return}if(!LISTEN()){toast('Connect your microphone first.');return}on=true;quiet=null;hiss=0;t0=performance.now();hg.textContent='Stop';micHiss()}}};
 const pace=()=>{if(!on||!document.body.contains(host))return;const el=(performance.now()-t0)/1000;const per=12;cyc=Math.floor(el/per);const p=el%per;const ball=host.querySelector('#vsball'),tx=host.querySelector('#vsbtxt');
  if(cyc>=5){on=false;tx.textContent='Done. Notice how much calmer and lower your breath feels.';host.querySelector('#vsbgo').textContent='Again';ball.style.transform='scale(.55)';return}
  const sc=p<4?.55+.45*(p/4):1-.45*((p-4)/8);ball.style.transform=`scale(${sc.toFixed(3)})`;tx.textContent=p<4?`Breathe in… ${Math.ceil(4-p)}`:`Hiss out… ${Math.ceil(12-p)}  (round ${cyc+1} of 5)`;raf=requestAnimationFrame(pace)};
 const tick=()=>{if(!on)return;const e=host.querySelector('#vshiss');if(e)e.textContent=((performance.now()-t0)/1000).toFixed(1)+' s';raf=requestAnimationFrame(tick)};
 /* a hiss is loud but unpitched: level well above the room, and no stable pitch */
 const micHiss=()=>{if(!on||!document.body.contains(host))return;const el=(performance.now()-t0)/1000;const db=vsDb();if(el<1){quiet=quiet==null?db:Math.max(quiet,db);host.querySelector('#vshiss').textContent='Quiet…';raf=requestAnimationFrame(micHiss);return}
  const loud=db>Math.max(quiet+10,-60);if(loud){if(!micHiss.s)micHiss.s=performance.now();micHiss.q=0;hiss=(performance.now()-micHiss.s)/1000}else if(micHiss.s){micHiss.q=(micHiss.q||0)+1;if(micHiss.q>20&&hiss>1){on=false;micHiss.s=0;finish(hiss);return}}
  host.querySelector('#vshiss').textContent=micHiss.s?hiss.toFixed(1)+' s':'Hiss now';if(el>60){on=false;finish(hiss);return}raf=requestAnimationFrame(micHiss)};
 const finish=s=>{micHiss.s=0;lastHiss=s;if(s>best){best=s;store.set('svhiss',+s.toFixed(1))}const L=store.get('svhissl',[])||[];L.push({d:todayKey(),s:+s.toFixed(1)});store.set('svhissl',L.slice(-60));render()};
 render()}
/* ---------- 4. dynamics: messa di voce (soft, swell, back to soft on one note) ---------- */
const VS_SHAPE=t=>t<1.5?0:t<5?(t-1.5)/3.5:t<9?1-(t-5)/4:0;
function vsDynWidget(host){const Z=vsZone();let target=Z.mid-2,on=false,raf=0,t0=0,P=[],last=null;
 const render=()=>{cancelAnimationFrame(raf);host.innerHTML=`<h3>Swell and fade (messa di voce)</h3><p class="hint">A classical exercise for control: start soft, grow to full voice, then fade back to soft, all on one note without the pitch moving. Follow the shaded shape. It takes 10 seconds.</p>${vsMicNote()}
  <div class="row" style="gap:10px;align-items:flex-end"><label class="popt">Note <select id="vsdn">${(()=>{let s='';for(let m=Z.lo;m<=Z.hi;m++)s+=`<option value="${m}" ${m===target?'selected':''}>${svName(m)}</option>`;return s})()}</select></label><button class="btn primary small" id="vsdgo">${ICON.play} ${on?'Stop':'Start'}</button></div>
  <canvas class="vscv" width="1520" height="300"></canvas><p class="hint" id="vsdst" aria-live="polite">${LISTEN()||IN_CLAUDE()?'Press Start: you\'ll hear the note, then follow the shape.':'Connect your microphone to see your volume.'}</p><div class="vsres">${last||''}</div>`;
  vsBindMic(host,render);host.querySelector('#vsdn').onchange=e=>{target=+e.target.value};
  host.querySelector('#vsdgo').onclick=()=>{if(on){on=false;return}const a=audio();if(!a)return;svPlayNote(target,a.currentTime+.05,1.4);on=true;P=[];t0=a.currentTime+1.6;draw()}};
 const draw=()=>{if(!document.body.contains(host)){on=false;return}const cv=host.querySelector('.vscv');const g=cv.getContext('2d');const W=760,H=150;g.setTransform(2,0,0,2,0,0);const el=AC.currentTime-t0;
  const m=vsMidi();if(el>=0&&el<=10.5){const db=vsDb();P.push({t:el,db,c:m!=null?(svFold(m,target)-target)*100:null})}
  g.clearRect(0,0,W,H);g.fillStyle=svCss('--surface-2');g.fillRect(0,0,W,H);const x=t=>20+t/10*(W-40),yv=v=>H-14-v*(H-28);g.fillStyle=svCss('--accent-soft');g.beginPath();g.moveTo(x(0),yv(0));for(let t=0;t<=10;t+=.1)g.lineTo(x(t),yv(VS_SHAPE(t)));g.lineTo(x(10),yv(0));g.fill();
  const v=P.filter(p=>p.db>-90);if(v.length>3){const lo=Math.min(...v.map(p=>p.db)),hi=Math.max(...v.map(p=>p.db));const nv=d=>hi-lo>3?(d-lo)/(hi-lo):.5;g.strokeStyle=svCss('--ink');g.lineWidth=2.5;g.beginPath();v.forEach((p,i)=>i?g.lineTo(x(p.t),yv(nv(p.db))):g.moveTo(x(p.t),yv(nv(p.db))));g.stroke()}
  const st=host.querySelector('#vsdst');if(st)st.textContent=el<0?'Listen…':el<1.5?'Start soft…':el<5?'Grow…':el<9?'Fade…':'Soft…';if(el>10.5||!on){on=false;finish();return}raf=requestAnimationFrame(draw)};
 const finish=()=>{const v=P.filter(p=>p.db>-75&&p.t>.2);if(v.length<20){last=`<p class="note">${IN_CLAUDE()?'Without the microphone I can\'t measure your volume. Listen back to a phone recording: you should hear a smooth swell and fade.':'I didn\'t hear enough. Sing a little louder at the peak.'}</p>`;render();return}
  const lo=Math.min(...v.map(p=>p.db)),hi=Math.max(...v.map(p=>p.db));const err=v.reduce((a,p)=>a+Math.abs((p.db-lo)/Math.max(3,hi-lo)-VS_SHAPE(p.t)),0)/v.length;const shape=Math.max(0,Math.round((1-err*1.6)*100));
  const pc=v.filter(p=>p.c!=null);const loud=pc.filter(p=>VS_SHAPE(p.t)>.7),soft=pc.filter(p=>VS_SHAPE(p.t)<.3);const av=a=>a.length?a.reduce((s,p)=>s+p.c,0)/a.length:0;const shift=Math.round(av(loud)-av(soft));
  const tips=[];if(hi-lo<8)tips.push(`Your loudest and softest differed by only ${Math.round(hi-lo)} dB. Start softer and let the middle grow more.`);else if(shape<60)tips.push('Try to make the swell gradual: no sudden jumps in volume.');
  if(pc.length>10&&Math.abs(shift)>=25)tips.push(`You went ${Math.abs(shift)} cents ${shift>0?'sharp':'flat'} as you got louder. ${shift>0?'Don\'t squeeze for volume: add breath, not tension.':'Keep the breath moving as you get louder.'}`);if(!tips.length)tips.push('Smooth and controlled. Try it on a higher note or a different vowel.');
  const B=store.get('svdyn',[])||[];B.push({d:todayKey(),shape,range:Math.round(hi-lo)});store.set('svdyn',B.slice(-60));
  last=`<div class="prgrid"><div><span class="prv">${shape}%</span><span class="hint">followed the shape</span></div><div><span class="prv">${Math.round(hi-lo)} dB</span><span class="hint">soft to loud</span></div>${pc.length>10?`<div><span class="prv">${shift>0?'+':''}${shift}</span><span class="hint">cents pitch change when loud</span></div>`:''}</div><ul>${tips.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`;render()};
 render()}
/* ---------- 5. sight-singing with solfège (the Kodály way: hear "do", then sing by scale step) ---------- */
const SOLF=['do','re','mi','fa','sol','la','ti'];const SOLF_ST=[0,2,4,5,7,9,11];
const VS_SS=[['l1','1 · do re mi','Steps between do, re and mi.',{deg:[0,1,2],len:4,leap:1}],['l2','2 · Five notes','do to sol, mostly steps.',{deg:[0,1,2,3,4],len:5,leap:2}],['l3','3 · The whole scale','do to high do, steps and thirds.',{deg:[0,1,2,3,4,5,6,7],len:6,leap:2}],['l4','4 · Leaps','Jumps around do, mi and sol.',{deg:[-3,0,2,4,7],len:6,leap:7}],['l5','5 · Minor (la-based)','la, ti, do, re, mi.',{deg:[-2,-1,0,1,2],len:6,leap:2,minor:true}]];
function vsDeg(d){const o=Math.floor(d/7);const i=((d%7)+7)%7;return{st:SOLF_ST[i]+12*o,name:SOLF[i]+(o>0?'′':o<0?'₁':'')}}
function vsMelody(cfg){const D=cfg.deg;const out=[];let cur=cfg.minor?-2:0;out.push(cur);for(let i=1;i<cfg.len;i++){const c=D.filter(d=>d!==cur&&Math.abs(d-cur)<=cfg.leap);cur=c[Math.floor(Math.random()*c.length)];out.push(cur)}if(!cfg.minor&&out[out.length-1]!==0&&D.includes(0)&&Math.abs(out[out.length-1])<=cfg.leap)out[out.length-1]=0;return out}
function vsSightWidget(host){let lvl=store.get('vssl','l1'),show='solf',mel=null,lane=null,last=null,bpm=72;
 const cfg=()=>VS_SS.find(x=>x[0]===lvl)[3];const doNote=()=>{const Z=vsZone();return Math.max(Z.lo+3,Math.min(Z.hi-8,Z.mid-3))};
 const build=()=>{const b=60/bpm;const D=doNote();const out=[];let t=0;const minor=cfg().minor;const tri=minor?[-3,0,4].map(x=>x-0):[0,4,7];
  tri.forEach(s=>out.push({m:D+(minor?s-0:s),d:b*.9,t:0,play:true,sing:false}));t+=b*1.5;
  mel.forEach(d=>{const v=vsDeg(d);out.push({m:D+v.st,d:b,t,play:false,sing:true,label:show==='solf'?v.name:show==='name'?svName(D+v.st):''});t+=b});return out};
 const render=()=>{host.innerHTML=`<h3>Sight-singing</h3><p class="hint">You hear the home chord, then sing the tune from the bars using solfège: do is home, and each name is a step of the scale. This is how Kodály and many choirs teach reading by ear. Use “Hear it” only after you've tried.</p>${vsMicNote()}
  ${pillsHTML('vssl',VS_SS.map(x=>[x[0],x[1]]),lvl)}<p class="o">${esc(VS_SS.find(x=>x[0]===lvl)[2])}</p>
  <div class="row">${pillsHTML('vsshow',[['solf','Solfège'],['name','Note names'],['none','No labels (by ear)']],show)}</div>
  <div class="row"><button class="btn primary small" id="vssgo">${mel?'Sing it again':'New tune'}</button>${mel?'<button class="btn small" id="vssnew">New tune</button><button class="btn small" id="vsshear">Hear it</button>':''}<label class="row hint" style="gap:6px">Tempo <input type="range" id="vssbpm" min="50" max="110" step="2" value="${bpm}" style="width:110px"> <span id="vssbv">${bpm}</span></label></div>
  ${mel?`<p class="vssolf">${mel.map(d=>`<span>${show==='name'?svName(doNote()+vsDeg(d).st):show==='none'?'?':vsDeg(d).name}</span>`).join('')}</p>`:''}
  <div class="svhost"></div><span class="hint svst" aria-live="polite"></span><p class="o svres" aria-live="polite">${last||''}</p>
  ${IN_CLAUDE()&&mel?'<div class="row"><span class="hint">How did it go?</span><button class="btn small" data-self="1">I got it</button><button class="btn small" data-self="0">Not yet</button></div>':''}`;
  vsBindMic(host,render);bindPills(host,(g,v)=>{if(g==='vssl'){lvl=v;store.set('vssl',v);mel=null}else if(g==='vsshow')show=v;render()});
  const sl=host.querySelector('#vssbpm');sl.oninput=()=>{bpm=+sl.value;host.querySelector('#vssbv').textContent=bpm};
  lane=svLane(host.querySelector('.svhost'),{onDone:r=>{const ok=r.heard&&r.pct>=75;last=!r.heard?(LISTEN()?'I didn\'t hear you. Check your microphone level.':''):`${r.pct}% in tune. ${ok?'Nice reading. Try a new tune.':'Press “Hear it”, then sing it again.'}`;if(r.heard)vsSightLog(lvl,r.pct);const e=host.querySelector('.svres');if(e)e.textContent=last}});
  const go=host.querySelector('#vssgo');go.onclick=()=>{if(lane&&lane.busy()){lane.stop();return}if(!mel)mel=vsMelody(cfg());render();const N=build();lane.play(N,svRange(N));const g2=host.querySelector('#vssgo');if(g2)g2.textContent='Stop'};
  const nw=host.querySelector('#vssnew');if(nw)nw.onclick=()=>{mel=vsMelody(cfg());last=null;render()};
  const hr=host.querySelector('#vsshear');if(hr)hr.onclick=()=>{const a=audio();if(!a)return;const b=60/bpm;const D=doNote();mel.forEach((d,i)=>svPlayNote(D+vsDeg(d).st,a.currentTime+.1+i*b,b*.9))};
  host.querySelectorAll('[data-self]').forEach(b=>b.onclick=()=>{vsSightLog(lvl,b.dataset.self==='1'?100:40);mel=vsMelody(cfg());toast(b.dataset.self==='1'?'Logged. Here\'s a new one.':'Logged. Try this one.');render()})};
 render()}
function vsSightLog(l,p){const S=store.get('vssight',{})||{};const r=S[l]||{n:0,best:0,ok:0};r.n++;r.best=Math.max(r.best,p);if(p>=75)r.ok++;S[l]=r;store.set('vssight',S)}
/* ---------- 6. the daily workout ---------- */
const VS_WORK=[
 {id:'breath',t:'Posture and breath',min:2,why:'Feet apart, knees soft, chin level. Low, quiet breaths wake up the breathing muscles before you sing.',mount:h=>vsBreathWidget(h)},
 {id:'sovt',t:'Straw or lip-trill sirens',min:2,why:'Singing through a straw or on a lip trill partly closes the mouth, which makes the vocal folds work more easily with less effort (Titze, 2006). Sirens gently stretch your whole range.',mount:h=>svLaneWidget(h,{title:'Sirens',hint:'Glide up and back down on a lip trill, through a straw, or on “ng”. Keep it light and smooth, especially where your voice wants to flip.',items:[['trill','Lip trill',''],['straw','Straw',''],['ng','On “ng”','']],build:(c,{call,bpm})=>{const Z=vsZone();const sp=Math.min(12,Z.hi-Z.lo-2);return vsUpDown([['g',0,sp,3],['g',sp,0,3]],{bpm,call,reps:3,step:2})}})},
 {id:'hum',t:'Hummed scales',min:2,why:'Humming keeps the throat relaxed while you find the notes. The pattern moves up through your comfortable range, then comes back down.',mount:h=>svLaneWidget(h,{title:'Hum the 5-note scale',hint:'1-2-3-4-5-4-3-2-1 on “mm”, moving up a semitone each time and then back down.',items:[['mm','Hum (mm)',''],['ah','Open to “ah”','']],build:(c,{call,bpm})=>vsUpDown([[0,1],[2,1],[4,1],[5,1],[7,1],[5,1],[4,1],[2,1],[0,2]],{bpm,call,reps:5})})},
 {id:'vfe',t:'Sustained “ee”',min:2,why:'From Stemple\'s Vocal Function Exercises, used by voice therapists and singers: hold a soft, forward “ee” as long as is comfortable. Try to beat yesterday\'s time.',mount:h=>vsSustainWidget(h,{title:'Hold a soft “ee”',hint:'Sing “ee” softly, with the sound buzzing at the front of your face, and hold it as long as is comfortable. Don\'t push for volume.',note:(()=>{const Z=vsZone();let f=Z.lo+2;while(((f%12)+12)%12!==5&&f<Z.hi)f++;return f<=Z.hi?f:Z.mid})(),mode:'free'})},
 {id:'glide',t:'Glides: lowest to highest',min:1,why:'Also from the Vocal Function Exercises: slow glides from bottom to top and back stretch and then shorten the vocal folds.',mount:h=>svLaneWidget(h,{title:'Glide on “knoll”',hint:'Glide slowly from your lowest comfortable note to your highest on “knoll” (oo-shaped lips), then back down. No pushing at the top.',items:[['up','Up and down','']],build:(c,{call,bpm})=>{const Z=vsZone();return[{m:Z.lo,glide:Z.hi,d:6,t:0,play:call,sing:!call},{m:Z.hi,glide:Z.lo,d:6,t:6.5,play:call,sing:!call},...(call?[{m:Z.lo,glide:Z.hi,d:6,t:13,play:false,sing:true},{m:Z.hi,glide:Z.lo,d:6,t:19.5,play:false,sing:true}]:[])]}})},
 {id:'agile',t:'Agility',min:2,why:'Quick, light scales train coordination for runs and riffs. Keep them light: speed comes from ease, not force.',mount:h=>svLaneWidget(h,{title:'Quick scales',hint:'Sing lightly on “ah” or “ee”. Start slow, then raise the tempo.',items:[['five','Five-note run',''],['nine','Nine-note scale',''],['arp','Arpeggio','']],build:(c,{call,bpm})=>{const P={five:[[0,.5],[2,.5],[4,.5],[5,.5],[7,.5],[5,.5],[4,.5],[2,.5],[0,1]],nine:[[0,.5],[2,.5],[4,.5],[5,.5],[7,.5],[9,.5],[11,.5],[12,.5],[14,.5],[12,.5],[11,.5],[9,.5],[7,.5],[5,.5],[4,.5],[2,.5],[0,1]],arp:[[0,.5],[4,.5],[7,.5],[12,.5],[16,.5],[12,.5],[7,.5],[4,.5],[0,1]]}[c];return vsUpDown(P,{bpm,call,reps:4})}})},
 {id:'dyn',t:'Swell and fade',min:1,why:'Messa di voce, a classical control exercise: grow and shrink the volume on one steady pitch.',mount:h=>vsDynWidget(h)},
 {id:'sight',t:'Sight-singing',min:2,why:'Train your inner ear: hear do, then sing a short tune by scale step.',mount:h=>vsSightWidget(h)},
 {id:'cool',t:'Cool-down',min:1,why:'Gentle descending sirens and a hum bring the voice back to speaking level. Singers who cool down report less vocal tiredness.',mount:h=>svLaneWidget(h,{title:'Cool-down',hint:'Gentle sighs down on “oo”, then hum a few comfortable notes. Quiet and easy.',items:[['sigh','Sigh down','']],build:(c,{call,bpm})=>{const Z=vsZone();const b=60/bpm;const out=[];let t=0;[0,-2,-4].forEach(o=>{const top=Math.min(Z.hi,Z.mid+5+o),bot=Math.max(Z.lo,top-7);const n={m:top,glide:bot,d:3*b};if(call){out.push({...n,t,play:true,sing:false});t+=n.d+b*.5}out.push({...n,t,play:!call,sing:true});t+=n.d+b*.75});return out}})}];
const VS_SHORT=['breath','sovt','hum','cool'];
function vsWorkout(host){const health=vsHealthToday();const short=health==='tired';const rest=health==='hoarse'||health==='pain';let list=short?VS_WORK.filter(s=>VS_SHORT.includes(s.id)):VS_WORK;if(health==='hoarse')list=VS_WORK.filter(s=>['breath','sovt','cool'].includes(s.id));
 const W=store.get('vswork',{})||{};const today=W[todayKey()]||{done:[]};let i=Math.max(0,list.findIndex(s=>!today.done.includes(s.id)));if(i<0)i=0;
 const render=()=>{const s=list[i];const n=today.done.filter(id=>list.some(x=>x.id===id)).length;const all=n>=list.length;
  host.innerHTML=`${health==='pain'?`<p class="callout">You said your voice hurts or has gone. Please don't sing today: rest it, and see a doctor if it doesn't improve within a few days or you have pain, trouble breathing or swallowing.</p>`:''}
  ${health==='hoarse'?'<p class="callout">You said your voice is hoarse, so today is a gentle 5-minute routine: breath, straw sirens and a cool-down only.</p>':short?'<p class="note">Your voice feels tired, so today is a short routine.</p>':''}
  <div class="vswk"><div class="row" style="justify-content:space-between;align-items:baseline"><b>${all?'Workout done today':`Step ${i+1} of ${list.length}`}</b><span class="hint">about ${list.reduce((a,x)=>a+x.min,0)} minutes · ${n} of ${list.length} done</span></div><i class="hbar"><i style="width:${Math.round(n/list.length*100)}%"></i></i>
  <ol class="vswsteps">${list.map((x,k)=>`<li class="${today.done.includes(x.id)?'done':''} ${k===i?'cur':''}"><button class="linkbtn" data-ws="${k}">${today.done.includes(x.id)?'✓':k+1} · ${esc(x.t)}</button></li>`).join('')}</ol></div>
  ${rest&&health==='pain'?'':`<section class="panel"><span class="eyebrow">Step ${i+1} · ${s.min} min</span><h3 style="margin-top:4px">${esc(s.t)}</h3><p class="hint">${esc(s.why)}</p><div class="vswbox stack"></div>
   <div class="row" style="margin-top:12px"><button class="btn primary" id="vswdone">${today.done.includes(s.id)?'Next step':'Done, next step'}</button>${i>0?'<button class="btn" id="vswback">Back</button>':''}</div></section>`}`;
  host.querySelectorAll('[data-ws]').forEach(b=>b.onclick=()=>{i=+b.dataset.ws;render()});const box=host.querySelector('.vswbox');if(box)s.mount(box);
  const d=host.querySelector('#vswdone');if(d)d.onclick=()=>{if(!today.done.includes(s.id)){today.done.push(s.id);W[todayKey()]=today;const ks=Object.keys(W).sort();ks.slice(0,-90).forEach(k=>delete W[k]);store.set('vswork',W);try{logPractice(s.min*60)}catch(e){}}
   stopSeq();if(i<list.length-1)i++;else{toast('Workout done. Drink some water.');try{const W2=store.get('warmlog',{});W2[todayKey()]=true;store.set('warmlog',W2)}catch(e){}}render();host.scrollIntoView({block:'start',behavior:'smooth'})};
  const bk=host.querySelector('#vswback');if(bk)bk.onclick=()=>{i--;render()}};
 render()}
/* ---------- 7. voice health ---------- */
const VS_FEEL=[['fresh','Fresh','Full workout today.'],['tired','A bit tired','A short, easy routine, then rest.'],['hoarse','Hoarse or scratchy','Gentle 5 minutes only, lots of water, no shouting or whispering.'],['pain','Painful or gone','Rest your voice today.']];
function vsHealthToday(){return((store.get('vshealth',{})||{})[todayKey()])||null}
function vsHoarseRun(){const H=store.get('vshealth',{})||{};const ks=Object.keys(H).filter(k=>H[k]==='hoarse'||H[k]==='pain').sort();if(!ks.length)return 0;const first=parseKey(ks[0]),last=parseKey(ks[ks.length-1]);const recent=ks.filter(k=>(new Date()-parseKey(k))/864e5<=35);if(recent.length<3)return 0;return Math.round((parseKey(recent[recent.length-1])-parseKey(recent[0]))/864e5)}
function vsHealthHTML(){const f=vsHealthToday();const run=vsHoarseRun();return`<section class="panel"><h3>How does your voice feel today?</h3><div class="row vsfeel">${VS_FEEL.map(([k,n])=>`<button class="pill" data-feel="${k}" aria-pressed="${f===k}">${n}</button>`).join('')}</div>${f?`<p>${esc(VS_FEEL.find(x=>x[0]===f)[2])} ${f!=='pain'?'<a href="#voice-workout">Today\'s workout</a> adjusts to this.':''}</p>`:''}
 ${run>=28?`<p class="callout">You've logged a hoarse or painful voice on and off for about ${Math.round(run/7)} weeks. Doctors' guidelines say hoarseness that doesn't clear within four weeks should be checked by an ENT specialist, who can look at your vocal folds.</p>`:''}</section>
 <section class="panel"><h3>See a doctor</h3><ul><li>If hoarseness lasts more than <b>four weeks</b> (the American Academy of Otolaryngology's guideline).</li><li><b>Sooner</b> if you have pain when you speak or sing, cough up blood, have trouble breathing or swallowing, find a lump in your neck, or lose your voice completely for more than a few days.</li><li>Professional and heavy voice users should get checked earlier rather than later.</li></ul><p class="hint">This is general guidance, not medical advice.</p></section>
 <section class="panel"><h3>Everyday habits</h3><dl class="tunel"><dt>Water</dt><dd>Sip water through the day. Steam (a hot shower or a bowl of hot water) helps the vocal folds directly.</dd><dt>Warm up and cool down</dt><dd>Five minutes before and after singing. Never start on your highest or loudest songs.</dd><dt>Rest</dt><dd>Plan quiet periods after long rehearsals. Your voice recovers like a muscle.</dd><dt>Don't push over noise</dt><dd>Shouting over loud bars, gigs or machines strains the voice more than singing. Use a microphone instead of forcing volume.</dd><dt>Whispering</dt><dd>Hard whispering can strain a tired voice. Speak softly instead.</dd><dt>Throat clearing</dt><dd>Swallow or sip water instead of clearing hard.</dd><dt>Sleep, reflux and smoke</dt><dd>Tiredness, acid reflux, smoking and vaping all show up in the voice.</dd><dt>Pain is a stop sign</dt><dd>Singing should never hurt. If it does, stop and rest.</dd></dl></section>`}
function vsWireHealth(root,after){root.querySelectorAll('[data-feel]').forEach(b=>b.onclick=()=>{const H=store.get('vshealth',{})||{};H[todayKey()]=b.dataset.feel;const ks=Object.keys(H).sort();ks.slice(0,-120).forEach(k=>delete H[k]);store.set('vshealth',H);after&&after()})}
/* ---------- 8. progress ---------- */
function vsProgressHTML(){const H=store.get('svrangeh',[])||[];const W=store.get('vswork',{})||{};const wk=Object.keys(W).filter(k=>(new Date()-parseKey(k))/864e5<7&&W[k].done.length).length;const S=store.get('vssight',{})||{};const sus=store.get('svsus',[])||[];const hiss=+store.get('svhiss',0)||0;
 const chart=H.length?`<svg class="vsrsvg" viewBox="0 0 560 ${H.length*18+30}" role="img" aria-label="Your range over time">${H.slice(-10).map((r,i)=>{const x=m=>70+(m-33)/(91-33)*480;return`<text x="64" y="${i*18+16}" text-anchor="end" class="vstt">${parseKey(r.date).toLocaleDateString(undefined,{day:'numeric',month:'short'})}</text><rect x="${x(r.lo)}" y="${i*18+6}" width="${x(r.hi)-x(r.lo)}" height="12" rx="6" class="vsyou"/><text x="${x(r.hi)+6}" y="${i*18+16}" class="vstt">${svName(r.lo)}–${svName(r.hi)}</text>`}).join('')}</svg>`:'<p class="hint">Measure your range to start tracking it.</p>';
 return`<section class="panel"><h3>Your progress</h3><div class="prgrid"><div><span class="prv">${wk}</span><span class="hint">workout days this week</span></div><div><span class="prv">${hiss?hiss.toFixed(1)+' s':'–'}</span><span class="hint">longest hiss</span></div><div><span class="prv">${+store.get('svsustain',0)||'–'}${store.get('svsustain',0)?' s':''}</span><span class="hint">longest held note</span></div><div><span class="prv">${sus.length?Math.round(sus.slice(-5).reduce((a,b)=>a+b.inTune,0)/Math.min(5,sus.length))+'%':'–'}</span><span class="hint">in tune, last 5 holds</span></div></div></section>
 <section class="panel"><h3>Range over time</h3>${chart}</section><section class="panel"><h3>Sight-singing</h3>${VS_SS.map(([k,n])=>{const r=S[k];return`<p><b>${esc(n)}</b> <span class="hint">${r?`${r.ok} of ${r.n} tunes at 75% or better · best ${r.best}%`:'not tried yet'}</span></p>`}).join('')}</section>`}
