const VS_TECHMAP={breath:'breath',sirens:'workout',headvoice:'range',falsetto:'range',mixvoice:'range',belt:'dynamics',vibratov:'sustain',runs:'workout',legatov:'sustain',diction:'sight',blend:'sight',scat:'sight'};
{const _vj=viewJTech;viewJTech=function(lv,o){_vj(lv,o);try{const inst=(o&&o.inst)||jtInst();if(inst!=='voice')return;main.querySelectorAll('.jtcard').forEach(d=>{const k=d.dataset.k;const T=techT('voice')[k];if(!T)return;let tab=VS_TECHMAP[k];if(!tab){const n=(T.name+' '+T.desc).toLowerCase();tab=/breath|support/.test(n)?'breath':/vibrato|sustain|hold|legato/.test(n)?'sustain':/range|head|falsetto|chest|mix|register|passaggio/.test(n)?'range':/loud|belt|dynamic|power/.test(n)?'dynamics':/read|interval|harmony|ear/.test(n)?'sight':'workout'}
 const lab={breath:'Breath trainer',sustain:'Hold & vibrato meter',range:'Range and register sirens',dynamics:'Swell and fade trainer',sight:'Sight-singing',workout:'Daily workout'}[tab];d.querySelector('summary').insertAdjacentHTML('afterend',`<p class="vstlink"><a class="btn small" href="#voice-${tab}">Practise it: ${lab}</a></p>`)})}catch(e){}}}
{const _pw=planWeekHTML;planWeekHTML=function(P,w,i,done){let h=_pw(P,w,i,done);try{if(P.inst==='voice'&&w.kind!=='check')h=h.replace('<div class="lgrid">','<div class="lgrid"><div class="ptone"><h4>Every session</h4><p>Start with the <a href="#voice-workout">Voice studio workout</a> (about 15 minutes, in your range), then the song.</p></div>')}catch(e){}return h}}
